  tooManyThreadMessages: 'too_many_thread_messages',
  tagsTooLarge: 'tags_too_large',
  tooManyNodesOrEdges: 'too_many_nodes_or_edges',
  invalidDocumentRoot: 'invalid_document_root',
  causalGap: 'causal_gap',
  reservedMapKey: 'reserved_map_key',
  retiredStoredShape: 'retired_stored_shape',
  retiredCommentPlane: 'retired_comment_plane',
  invalidPath: 'invalid_path',
  unreadableDocumentMeta: 'unreadable_document_meta',
  documentKindChanged: 'document_kind_changed',
  documentNameTooLong: 'document_name_too_long',
  folderNameRefused: 'folder_name_refused',
  tooManyDocuments: 'too_many_documents',
  tooManyFolders: 'too_many_folders',
  tooManyWorkspaces: 'too_many_workspaces',
  tooManyVersions: 'too_many_versions',
  documentNotFound: 'document_not_found',
  documentEngineTrap: 'document_engine_trap',
  documentKindMismatch: 'document_kind_mismatch',
  workspaceNotFound: 'workspace_not_found',
  documentPathTaken: 'document_path_taken',
  displayNameTaken: 'display_name_taken',
  workspaceSegmentTaken: 'workspace_segment_taken',
  workspaceSegmentUnusable: 'workspace_segment_unusable',
  documentNameConflict: 'document_name_conflict',
  documentHasDescendants: 'document_has_descendants',
  documentMoveIntoSelf: 'document_move_into_self',
  cannotPlaceCopy: 'cannot_place_copy',
  documentSerializeFailed: 'document_serialize_failed',
  storedDocumentUnsupportedVersion: 'stored_document_unsupported_version',
  corruptStoredData: 'corrupt_stored_data',
  okfParseFailed: 'okf_parse_failed',
  okfNotYamlSafe: 'okf_not_yaml_safe',
  tagNotInLibrary: 'tag_not_in_library',
  facetWriteRejected: 'facet_write_rejected',
  searchNeedsQueryOrFilter: 'search_needs_query_or_filter',
